  expectRun({ A: 500, B: 0 }, (c) => escrow.transfer(c, "A", "A", 100), "SameAccount");
  expectRun({ A: 500, B: 0 }, (c) => escrow.transfer(c, "A", "B", 0), "BadAmount");
});

