  expectRun({ A: 500, B: 0 }, (c) => escrow.move(c, "A", "B", 0), "ok", { A: 500, B: 0 });
  expectRun({ A: 500, B: 0 }, (c) => escrow.move(c, "A", "B", 100), "ok", { A: 400, B: 100 });
  expectRun({ A: 0 }, (c) => escrow.move(c, "A", "A", 0), "ok", { A: 0 });
});

